export const getProductsByCategory = (categoryId) => {
  if (categoryId === 'all') return vegetables
  return vegetables.filter(v => v.category === categoryId)
}

export const getProductById = (id) => {
  return vegetables.find(v => v.id === parseInt(id))
}

export const searchProducts = (query) => {
  const lowerQuery = query.toLowerCase()
  return vegetables.filter(v => 
    v.name.toLowerCase().includes(lowerQuery) ||
    v.category.toLowerCase().includes(lowerQuery) ||
    v.tags.some(tag => tag.toLowerCase().includes(lowerQuery))
  )
}

export const getFeaturedProducts = () => {
  return vegetables.filter(v => v.tags.includes('popular') || v.rating >= 4.8).slice(0, 8)
}

export const getOrganicProducts = () => {
  return vegetables.filter(v => v.organic)
}

export const getInStockProducts = () => {
  return vegetables.filter(v => v.inStock)
}